76	    /**
77	     * Monotonically increasing sequence for the structured OWNER_CREATED audit events, incremented
78	     * once per successful create so every emitted event carries a strictly greater {@code seq} than
79	     * the one before it.
80	     */
81	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
82	        new java.util.concurrent.atomic.AtomicLong();
83	
84	    /**
85	     * The request header carrying a client-supplied idempotency token for owner creation. When a
86	     * create repeats with a token already seen, the originally created owner is returned with 200
87	     * instead of creating a duplicate.
88	     */
89	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
90	
91	    /**
92	     * Remembers, per idempotency key, the id of the owner created by the first request that carried
93	     * that key, so a repeat with the same key resolves back to the original owner instead of
94	     * creating a duplicate.
95	     */
96	    private final java.util.Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
