116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        boolean bulkSignupWarning = isBulkSignupWarning();
129	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
130	        ownerDtos.forEach(ownerDto -> {
131	            ownerDto.setBulkSignupWarning(bulkSignupWarning);
132	            ownerDto.setCapacityWarning(isCityApproachingCapacity(ownerDto.getCity()));
133	            ownerDto.setRiskFlag(computeRiskFlag(ownerDto.getPossibleDuplicate(),
134	                ownerDto.getEmail(), ownerDto.getCity()));
135	        });
136	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
137	    }
