153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
156	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
157	        // owner originally created for that key with 200, instead of creating a duplicate.
158	        String idempotencyKey = currentIdempotencyKey();
159	        if (idempotencyKey != null) {
160	            Integer existingId = idempotentCreates.get(idempotencyKey);
161	            if (existingId != null) {
162	                Owner existing = this.clinicService.findOwnerById(existingId);
163	                if (existing != null) {
164	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
165	                    existingDto.setBulkSignupWarning(isBulkSignupWarning());
166	                    existingDto.setCapacityWarning(isCityApproachingCapacity(existing.getCity()));
167	                    existingDto.setRiskFlag(computeRiskFlag(existing.getPossibleDuplicate(),
168	                        existing.getEmail(), existing.getCity()));
169	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
170	                }
171	            }
172	        }
173	        // Prefer the structured address fields when present; the flat 'address' input remains accepted
174	        // for backward compatibility. When structured, the stored/returned address is the composed
175	        // normalized addressLine1 (with a single space and the normalized addressLine2 appended when
176	        // addressLine2 is present); otherwise it is the normalized flat 'address'.
177	        boolean structured = !isBlank(ownerFieldsDto.getAddressLine1());
178	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
179	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
180	        String address;
181	        if (structured) {
182	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
183	        } else {
184	            address = normalizeAddress(ownerFieldsDto.getAddress());
185	        }
186	        List<String> missingFields = new ArrayList<>();
187	        if (isBlank(ownerFieldsDto.getFirstName())) {
188	            missingFields.add("firstName");
189	        }
190	        if (isBlank(ownerFieldsDto.getLastName())) {
191	            missingFields.add("lastName");
192	        }
193	        if (isBlank(address)) {
194	            missingFields.add("address");
195	        }
196	        if (isBlank(ownerFieldsDto.getCity())) {
197	            missingFields.add("city");
198	        }
199	        if (isBlank(ownerFieldsDto.getTelephone())) {
200	            missingFields.add("telephone");
201	        }
202	        if (!missingFields.isEmpty()) {
203	            throw new MissingOwnerFieldsException(missingFields);
204	        }
205	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
206	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
207	        HttpHeaders headers = new HttpHeaders();
208	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
209	        owner.setAddress(address);
210	        owner.setAddressLine1(structured ? addressLine1 : null);
211	        owner.setAddressLine2(structured && !addressLine2.isEmpty() ? addressLine2 : null);
212	        owner.setTelephone(telephone);
213	        validateEmailDomain(owner.getEmail());
214	        validatePostcode(owner.getPostcode(), owner.getRegion());
215	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
216	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
217	        // explicit link. This computed value drives duplicate detection and the household size.
218	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
219	        // A new owner may join an existing household (same computed householdId); rather than being
220	        // rejected, the joiner is admitted with a capped membership level (see below). The householdId
221	        // no longer feeds duplicate detection.
222	        // Duplicate detection is consolidated into the single derived identity key (telephone, email
223	        // and the last name's Soundex): a create is rejected when the new owner's whole identity key
224	        // equals an existing owner's.
225	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
226	            throw new DuplicateIdentityException(owner.getIdentityKey());
227	        }
228	        if (isCityAtCapacity(owner.getCity())) {
229	            throw new CityAtCapacityException(owner.getCity());
230	        }
231	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
232	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
233	        }
234	        LocalDate effectiveDate = owner.getRegistrationDate() != null
235	            ? owner.getRegistrationDate() : LocalDate.now();
236	        LocalDate registrationDate = toBusinessDay(effectiveDate);
237	        if (isDailyRegistrationLimitReached(registrationDate)) {
238	            throw new DailyRegistrationLimitException(registrationDate);
239	        }
240	        owner.setRegistrationDate(registrationDate);
241	        owner.setMemberId(deduplicateMemberId(memberIdFor(owner)));
242	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
243	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
244	        owner.setMembershipLevel(cappedMembershipLevel(owner));
245	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
246	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
247	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
248	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
249	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
250	        this.clinicService.saveOwner(owner);
251	        if (idempotencyKey != null) {
252	            idempotentCreates.put(idempotencyKey, owner.getId());
253	        }
254	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
255	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
256	        AUDIT.info(ownerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner));
257	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
258	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
259	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
260	        ownerDto.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
261	        ownerDto.setRiskFlag(computeRiskFlag(owner.getPossibleDuplicate(), owner.getEmail(), owner.getCity()));
262	        headers.setLocation(UriComponentsBuilder.newInstance()
263	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
264	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
265	    }
