269	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
270	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
271	        if (currentOwner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        currentOwner.setAddress(ownerFieldsDto.getAddress());
275	        currentOwner.setCity(ownerFieldsDto.getCity());
276	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
277	        currentOwner.setLastName(ownerFieldsDto.getLastName());
278	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
279	        this.clinicService.saveOwner(currentOwner);
280	        OwnerDto ownerDto = ownerMapper.toOwnerDto(currentOwner);
281	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
282	        ownerDto.setCapacityWarning(isCityApproachingCapacity(currentOwner.getCity()));
283	        ownerDto.setRiskFlag(computeRiskFlag(currentOwner.getPossibleDuplicate(),
284	            currentOwner.getEmail(), currentOwner.getCity()));
285	        return new ResponseEntity<>(ownerDto, HttpStatus.NO_CONTENT);
286	    }
