288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Transactional
290	    @Override
291	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        // Soft delete: retain the row, flag it deleted. The owner remains readable via GET, but
297	        // duplicate/identity detection on create ignores owners flagged deleted.
298	        owner.setDeleted(true);
299	        this.clinicService.saveOwner(owner);
300	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
301	    }
