368	    private static boolean isBlank(String value) {
369	        return value == null || value.isBlank();
370	    }
371	
372	    /**
373	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when the
374	     * header is absent, blank, or there is no bound request. A present, non-blank value is trimmed.
375	     *
376	     * @return the trimmed idempotency key, or {@code null} when none was supplied
377	     */
378	    private static String currentIdempotencyKey() {
379	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
380	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
381	            return null;
382	        }
383	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
384	        return isBlank(key) ? null : key.trim();
385	    }
386	
387	    /**
388	     * The set of disposable email domains that owners may not register with. Compared
389	     * case-insensitively against the domain part of the supplied email.
390	     */
391	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
392	        "mailinator.com", "tempmail.com", "guerrillamail.com");
393	
394	    /**
395	     * The provider (second-level) labels of the disposable blocklist domains ({@code mailinator},
396	     * {@code tempmail}, {@code guerrillamail}), used to recognise domains that are
397	     * <em>disposable-adjacent</em>: not on the exact blocklist (so accepted at create) but clearly a
398	     * variant of a known disposable provider. Derived from {@link #DISPOSABLE_EMAIL_DOMAINS} so the
399	     * two stay in sync.
400	     */
401	    private static final java.util.Set<String> DISPOSABLE_PROVIDER_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
402	        .map(OwnerRestControllerV1::secondLevelLabel)
403	        .filter(java.util.Objects::nonNull)
404	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
405	
406	    /**
407	     * The second-level label of a dotted domain, i.e. the label immediately preceding the top-level
408	     * label ({@code mailinator.com -> mailinator}, {@code sub.tempmail.net -> tempmail}). Returns
409	     * {@code null} for a {@code null}, blank, or single-label value that has no second level.
410	     *
411	     * @param domain the (already lower-cased) domain
412	     * @return the second-level label, or {@code null} when there is none
413	     */
414	    private static String secondLevelLabel(String domain) {
415	        if (isBlank(domain)) {
416	            return null;
417	        }
418	        String[] labels = domain.split("\\.");
419	        return labels.length < 2 ? null : labels[labels.length - 2];
420	    }
421	
422	    /**
423	     * Determines whether an email's domain is <em>disposable-adjacent</em>: a domain that is not
424	     * itself on the {@link #DISPOSABLE_EMAIL_DOMAINS disposable blocklist} (those are rejected
425	     * outright at create) but is nonetheless a variant of a known disposable provider — a subdomain
426	     * of a blocklisted domain, or a domain sharing a blocklisted provider's second-level label under
427	     * a different top-level domain (e.g. {@code mailinator.net} or {@code sub.tempmail.com}). Email is
428	     * optional; a {@code null}, blank, or {@code '@'}-less value is not adjacent. The domain is
429	     * compared case-insensitively.
430	     *
431	     * @param email the owner's email (may be {@code null})
432	     * @return {@code true} if the email's domain is disposable-adjacent
433	     */
434	    private static boolean isDisposableAdjacent(String email) {
435	        if (isBlank(email)) {
436	            return false;
437	        }
438	        int at = email.lastIndexOf('@');
439	        if (at < 0) {
440	            return false;
441	        }
442	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
443	        if (domain.isEmpty() || DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
444	            return false;
445	        }
446	        String providerLabel = secondLevelLabel(domain);
447	        return providerLabel != null && DISPOSABLE_PROVIDER_LABELS.contains(providerLabel);
448	    }
449	
450	    /**
451	     * Determines whether an owner warrants a {@code riskFlag}: true when any of the following hold —
452	     * the owner is a possible (soft) duplicate, its email domain is
453	     * {@link #isDisposableAdjacent(String) disposable-adjacent}, or its city is over its soft capacity
454	     * (the {@link #isCityApproachingCapacity(String) soft-capacity} threshold that raises
455	     * {@code capacityWarning}); otherwise false.
456	     *
457	     * @param possibleDuplicate whether the owner is flagged a possible duplicate
458	     * @param email the owner's email (may be {@code null})
459	     * @param city the owner's city
460	     * @return {@code true} if the owner should be risk-flagged
461	     */
462	    private boolean computeRiskFlag(Boolean possibleDuplicate, String email, String city) {
463	        return Boolean.TRUE.equals(possibleDuplicate)
464	            || isDisposableAdjacent(email)
465	            || isCityApproachingCapacity(city);
466	    }
467	
468	    /**
469	     * Rejects an owner whose email domain is on the disposable-domain blocklist
470	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
471	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
472	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
473	     * case-insensitively; the stored email is already lower-cased.
474	     *
475	     * @param email the owner's email (may be {@code null})
476	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
477	     */
478	    private static void validateEmailDomain(String email) {
479	        if (isBlank(email)) {
480	            return;
481	        }
482	        int at = email.lastIndexOf('@');
483	        if (at < 0) {
484	            return;
485	        }
486	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
487	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
488	            throw new DisposableEmailDomainException(email);
489	        }
490	    }
491	
492	    /**
493	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
494	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
495	     */
496	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
497	        "NSW", new int[] {2000, 2099},
498	        "VIC", new int[] {3000, 3099},
499	        "QLD", new int[] {4000, 4099});
500	
501	    /**
502	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
503	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
504	     * present, the value has already passed the 4-digit format check (Bean Validation on the
505	     * request body); this enforces that it falls within the inclusive range for the city's region
506	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
507	     *
508	     * @param postcode the supplied postcode (may be {@code null})
509	     * @param region the owner's locality/region derived from its city
510	     * @throws InvalidPostcodeException if the postcode is out of range for the region
511	     */
512	    private static void validatePostcode(String postcode, String region) {
513	        if (isBlank(postcode)) {
514	            return;
515	        }
516	        int[] range = REGION_POSTCODES.get(region);
517	        if (range == null) {
518	            return;
519	        }
520	        int value;
521	        try {
522	            value = Integer.parseInt(postcode);
523	        }
524	        catch (NumberFormatException e) {
525	            throw new InvalidPostcodeException(postcode);
526	        }
527	        if (value < range[0] || value > range[1]) {
528	            throw new InvalidPostcodeException(postcode);
529	        }
530	    }
