532	    /**
533	     * Normalizes a street address into the canonical form stored on and returned for a newly
534	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
535	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
536	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
537	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
538	     * value is what gets persisted, echoed back, and used for every address comparison (household
539	     * duplicate detection and the shared household identifier).
540	     *
541	     * @param rawAddress the address value as supplied by the client
542	     * @return the normalized address (possibly empty, never {@code null})
543	     */
544	    private static String normalizeAddress(String rawAddress) {
545	        if (rawAddress == null) {
546	            return "";
547	        }
548	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
549	        if (collapsed.isEmpty()) {
550	            return "";
551	        }
552	        String[] tokens = collapsed.split(" ");
553	        StringBuilder sb = new StringBuilder(collapsed.length());
554	        for (int i = 0; i < tokens.length; i++) {
555	            String token = tokens[i];
556	            switch (token) {
557	                case "ST" -> token = "STREET";
558	                case "RD" -> token = "ROAD";
559	                case "AVE" -> token = "AVENUE";
560	                default -> { }
561	            }
562	            if (i > 0) {
563	                sb.append(' ');
564	            }
565	            sb.append(token);
566	        }
567	        return sb.toString();
568	    }
