573	    /**
574	     * The calendar year in which the fiscal year containing {@code date} began. The fiscal year
575	     * starts on 1 July, so a date in July through December belongs to a fiscal year that began in
576	     * its own calendar year, while a date in January through June belongs to one that began in the
577	     * previous calendar year.
578	     */
579	    private static int fiscalYearStart(LocalDate date) {
580	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH.getValue() ? date.getYear() : date.getYear() - 1;
581	    }
