583	    /**
584	     * Builds the member id assigned to a newly created owner, formatted
585	     * {@code <REGION><FY><HASH8><CHK>}: {@code REGION} is the region derived from the owner's
586	     * postcode (see {@link Owner#getRegion()}); {@code FY} is the two-digit fiscal year of the
587	     * (business-day-adjusted) {@code registrationDate} (the fiscal year starts on 1 July);
588	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
589	     * normalized (E.164) telephone concatenated with its last name; and {@code CHK} is a single Luhn
590	     * check digit computed over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D5}).
591	     * No sequence number is involved, so the id depends only on the owner's own region, fiscal year
592	     * and identity.
593	     *
594	     * @param owner the owner being created, with telephone normalized and registrationDate/postcode set
595	     * @return the member id to assign
596	     */
597	    private static String memberIdFor(Owner owner) {
598	        String fiscalYear = String.format("%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
599	        String base = owner.getRegion() + fiscalYear
600	            + telephoneNameHash(owner.getTelephone(), owner.getLastName());
601	        return base + luhnCheckDigit(base);
602	    }
603	
604	    /**
605	     * The single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
606	     * characters are ignored; the standard Luhn algorithm doubles every second digit from the right
607	     * (subtracting 9 when the result exceeds 9) and the check digit is {@code (10 - (sum % 10)) % 10}.
608	     *
609	     * @param value the string whose contained digits are checked
610	     * @return the Luhn check digit
611	     */
612	    private static int luhnCheckDigit(String value) {
613	        int sum = 0;
614	        boolean dbl = true;
615	        for (int i = value.length() - 1; i >= 0; i--) {
616	            char c = value.charAt(i);
617	            if (c < '0' || c > '9') {
618	                continue;
619	            }
620	            int d = c - '0';
621	            if (dbl) {
622	                d *= 2;
623	                if (d > 9) {
624	                    d -= 9;
625	                }
626	            }
627	            sum += d;
628	            dbl = !dbl;
629	        }
630	        return (10 - (sum % 10)) % 10;
631	    }
