660	    /**
661	     * De-duplicates a freshly computed member id against the ids already assigned to existing
662	     * owners. When no existing owner carries the given id it is returned unchanged; otherwise the
663	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields an id no existing owner holds is
664	     * appended, guaranteeing distinct owners always receive distinct member ids.
665	     *
666	     * @param memberId the member id computed for the owner being created
667	     * @return the de-duplicated member id, unique among existing owners
668	     */
669	    private String deduplicateMemberId(String memberId) {
670	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
671	            .map(Owner::getMemberId)
672	            .filter(java.util.Objects::nonNull)
673	            .collect(java.util.stream.Collectors.toSet());
674	        if (!existing.contains(memberId)) {
675	            return memberId;
676	        }
677	        int n = 2;
678	        while (existing.contains(memberId + "-" + n)) {
679	            n++;
680	        }
681	        return memberId + "-" + n;
682	    }
