684	    /**
685	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
686	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
687	     * last name.
688	     *
689	     * @param normalizedTelephone the owner's telephone in E.164 form
690	     * @param lastName the owner's last name
691	     * @return the 8-character upper-case hex hash
692	     */
693	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
694	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
695	            + (lastName == null ? "" : lastName);
696	        try {
697	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
698	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
699	            StringBuilder sb = new StringBuilder(digest.length * 2);
700	            for (byte b : digest) {
701	                sb.append(String.format("%02x", b));
702	            }
703	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
704	        }
705	        catch (java.security.NoSuchAlgorithmException e) {
706	            throw new IllegalStateException("SHA-256 not available", e);
707	        }
708	    }
