710	    /**
711	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
712	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
713	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
714	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
715	     * the national number must match the country code: {@code +61} requires 9 national digits and
716	     * {@code +1} requires 10.
717	     *
718	     * @param rawTelephone the telephone value as supplied by the client
719	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
720	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
721	     */
722	    private static String normalizeTelephone(String rawTelephone) {
723	        if (rawTelephone == null) {
724	            throw new InvalidTelephoneException(rawTelephone);
725	        }
726	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
727	        String e164;
728	        if (cleaned.startsWith("+")) {
729	            String digits = cleaned.substring(1);
730	            if (!digits.matches("[0-9]+")) {
731	                throw new InvalidTelephoneException(rawTelephone);
732	            }
733	            e164 = "+" + digits;
734	        } else {
735	            if (!cleaned.matches("[0-9]+")) {
736	                throw new InvalidTelephoneException(rawTelephone);
737	            }
738	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
739	            e164 = "+61" + national;
740	        }
741	        int digitCount = e164.length() - 1;
742	        if (digitCount < 8 || digitCount > 15) {
743	            throw new InvalidTelephoneException(rawTelephone);
744	        }
745	        if (e164.startsWith("+61")) {
746	            if (e164.length() - "+61".length() != 9) {
747	                throw new InvalidTelephoneException(rawTelephone);
748	            }
749	        }
750	        else if (e164.startsWith("+1")) {
751	            if (e164.length() - "+1".length() != 10) {
752	                throw new InvalidTelephoneException(rawTelephone);
753	            }
754	        }
755	        return e164;
756	    }
