774	    /**
775	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
776	     * whose last name has the same Soundex code and whose postcode matches, but whose whole identity
777	     * key <em>differs</em> (so it is not a hard duplicate). Because the telephone is part of the
778	     * identity key, two owners sharing a last name (by Soundex) and postcode but carrying different
779	     * telephones fall here rather than being rejected. Such a create is not rejected, but is flagged.
780	     * An owner with no postcode can never be a soft duplicate. When several owners match, the earliest
781	     * (lowest id) is returned so the result is deterministic.
782	     *
783	     * @param owner the owner being created (telephone already normalized, postcode set)
784	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
785	     */
786	    private Integer possibleDuplicateOf(Owner owner) {
787	        if (isBlank(owner.getPostcode())) {
788	            return null;
789	        }
790	        String lastNameSoundex = Owner.soundex(owner.getLastName());
791	        String identityKey = owner.getIdentityKey();
792	        return this.clinicService.findAllOwners().stream()
793	            .filter(existing -> existing.getId() != null
794	                && !existing.isDeleted()
795	                && Owner.soundex(existing.getLastName()).equals(lastNameSoundex)
796	                && owner.getPostcode().equals(existing.getPostcode())
797	                && !identityKey.equals(existing.getIdentityKey()))
798	            .map(Owner::getId)
799	            .min(Integer::compareTo)
800	            .orElse(null);
801	    }
