985	        int naturalLevel = owner.getComputedMembershipLevel();
986	        String householdId = owner.getHouseholdId();
987	        if (householdId == null) {
988	            return naturalLevel;
989	        }
990	        java.util.OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
991	            .filter(existing -> existing.getId() != null
992	                && !existing.isDeleted()
993	                && householdId.equals(existing.getHouseholdId()))
994	            .mapToInt(Owner::getMembershipLevel)
995	            .max();
