1013	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
1014	        try {
1015	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
1016	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
1017	            StringBuilder sb = new StringBuilder(digest.length * 2);
1018	            for (byte b : digest) {
